import { fetchConversationUnreadCount } from '../api/message';
import { isFullMode } from './appMode';

const MESSAGE_TAB_INDEX = 2;
const REFRESH_INTERVAL = 20000;

let cachedUnreadCount = 0;
let lastRefreshedAt = 0;
let refreshPromise = null;

export function setMessageTabBadge(value) {
	const unreadCount = Math.max(0, Number(value || 0));
	cachedUnreadCount = unreadCount;

	try {
		if (!unreadCount) {
			uni.removeTabBarBadge({ index: MESSAGE_TAB_INDEX, fail: () => {} });
			return unreadCount;
		}

		uni.setTabBarBadge({
			index: MESSAGE_TAB_INDEX,
			text: unreadCount > 99 ? '99+' : String(unreadCount),
			fail: () => {}
		});
	} catch (error) {}

	return unreadCount;
}

export function refreshMessageTabBadge(options = {}) {
	if (!isFullMode()) return Promise.resolve(setMessageTabBadge(0));
	const force = Boolean(options.force);
	if (!force && Date.now() - lastRefreshedAt < REFRESH_INTERVAL) {
		return Promise.resolve(setMessageTabBadge(cachedUnreadCount));
	}
	if (refreshPromise) return refreshPromise;

	refreshPromise = fetchConversationUnreadCount()
		.then((result = {}) => {
			lastRefreshedAt = Date.now();
			return setMessageTabBadge(result.unreadCount);
		})
		.catch(() => cachedUnreadCount)
		.finally(() => {
			refreshPromise = null;
		});

	return refreshPromise;
}
